<div class="ret-field"><label>{{ t('Items / Variants','পণ্য / ভ্যারিয়েন্ট') }}</label><div id="ret-items"></div><button type="button" class="ret-btn alt" id="ret-add-item">+ {{ t('Add Item','পণ্য যোগ করুন') }}</button></div>
@unless($purchaseMode??false)
<div class="ret-field"><label for="ret-barcode">{{ t('Scan barcode / SKU','বারকোড / SKU স্ক্যান করুন') }}</label><input class="ret-input" id="ret-barcode" type="search" autocomplete="off" placeholder="{{ t('Scan and press Enter','স্ক্যান করে Enter চাপুন') }}"><small id="ret-barcode-status" role="status" class="ret-help"></small></div>
@endunless
<template id="ret-line-template"><div class="ret-cart-row {{ ($purchaseMode??false)?'purchase':'' }}"><select name="items[__N__][variant_id]" class="ret-input" required><option value="">{{ t('Choose product / variant','পণ্য / ভ্যারিয়েন্ট বাছাই') }}</option>
 @foreach($variants as $variant)<option value="{{ $variant->id }}" data-barcode="{{ $variant->barcode }}" data-product-barcode="{{ $variant->product?->barcode }}" data-sku="{{ $variant->sku }}" data-product-sku="{{ $variant->product?->sku }}" data-price="{{ $purchaseMode??false ? $variant->cost : $variant->price }}">{{ $variant->product?->name }} — {{ $variant->sku }} @unless($purchaseMode??false){{ $variant->barcode ? " · ".$variant->barcode : ($variant->product?->barcode ? " · ".$variant->product->barcode : "") }}@endunless ({{ number_format($variant->stock,2) }})</option>@endforeach
 </select><input class="ret-input" type="number" name="items[__N__][quantity]" min="0.001" step="0.001" value="1" required aria-label="Quantity">
 @if($purchaseMode??false)<input class="ret-input" type="number" name="items[__N__][cost]" min="0" step=".01" placeholder="{{ t('Unit cost','ক্রয়মূল্য') }}" required>@else<span class="ret-help">{{ t('Price from catalog','মূল্য ক্যাটালগ অনুযায়ী') }}</span>@endif
 <button type="button" class="ret-btn alt ret-delete">×</button></div></template>
<script>
 document.addEventListener('DOMContentLoaded',()=>{const holder=document.getElementById('ret-items'),template=document.getElementById('ret-line-template');if(!holder||!template)return;let n=0;
 const add=()=>{const block=template.innerHTML.replaceAll('__N__',String(n++));holder.insertAdjacentHTML('beforeend',block);const row=holder.lastElementChild;row.querySelector('.ret-delete').onclick=()=>row.remove();const sel=row.querySelector('select');sel.onchange=()=>{const cost=row.querySelector('input[name$="[cost]"]');if(cost&&sel.selectedOptions[0])cost.value=sel.selectedOptions[0].dataset.price||0;};return row;};
 document.getElementById('ret-add-item').onclick=add;add();
 const scan=document.getElementById('ret-barcode'),status=document.getElementById('ret-barcode-status');
 if(scan)scan.addEventListener('keydown',e=>{if(e.key!=='Enter')return;e.preventDefault();const term=scan.value.trim().toLowerCase();if(!term)return;const options=Array.from(template.content.querySelectorAll('option')).filter(o=>o.value&&[o.dataset.barcode,o.dataset.productBarcode,o.dataset.sku,o.dataset.productSku].some(v=>String(v??'').toLowerCase()===term));if(options.length!==1){status.textContent=options.length?@json(t('Multiple variants match. Select the correct variant manually.','একাধিক ভ্যারিয়েন্ট পাওয়া গেছে। সঠিক ভ্যারিয়েন্ট নির্বাচন করুন।')):@json(t('No matching product.','পণ্য পাওয়া যায়নি।'));return;}const id=options[0].value,rows=Array.from(holder.children),existing=rows.find(r=>r.querySelector('select').value===id);if(existing){const qty=existing.querySelector('input[name$="[quantity]"]');qty.value=Number(qty.value||0)+1;}else{const row=rows.find(r=>!r.querySelector('select').value)||add();const sel=row.querySelector('select');sel.value=id;sel.dispatchEvent(new Event('change'));}scan.value='';status.textContent='';});});
</script>
